+
+    queue.enqueue(pageId);
+    queue.abandon([pageId]);
+    queue.enqueue(pageId);
+    await vi.advanceTimersByTimeAsync(DRAIN_INTERVAL_MS + RETRY_BACKOFF_MS);
+
+    expect(idsExtracted()).toEqual([pageId]);
+  });
+});

